import unittest
from solution import parse_records

class VisibleTests(unittest.TestCase):
    def test_plain_csv(self):
        self.assertEqual(parse_records("name,team\nAda,infra\n"), [{"name": "Ada", "team": "infra"}])

    def test_quoted_comma(self):
        self.assertEqual(parse_records('name,note\nAda,"hello, world"\n'), [{"name": "Ada", "note": "hello, world"}])

    def test_escaped_quote(self):
        self.assertEqual(parse_records('name,note\nAda,"says ""yes"""\n'), [{"name": "Ada", "note": 'says "yes"'}])

