import unittest
from solution import parse_records

class HiddenTests(unittest.TestCase):
    def test_embedded_newline(self):
        self.assertEqual(parse_records('id,note\n1,"line one\nline two"\n'), [{"id": "1", "note": "line one\nline two"}])

    def test_crlf(self):
        self.assertEqual(parse_records("id,name\r\n1,Ada\r\n2,Lin\r\n"), [{"id": "1", "name": "Ada"}, {"id": "2", "name": "Lin"}])

    def test_blank_rows_empty_and_header_only(self):
        self.assertEqual(parse_records(""), [])
        self.assertEqual(parse_records("id,name\n"), [])
        self.assertEqual(parse_records("id,name\n\n1,Ada\n\n"), [{"id": "1", "name": "Ada"}])

    def test_empty_cells_and_whitespace(self):
        self.assertEqual(parse_records('id,note\n1,\n2,"  keep  "\n'), [{"id": "1", "note": ""}, {"id": "2", "note": "  keep  "}])
